<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $descOrden = "CLIP GRANDE TROQUELADO"; $descProcesoActual = "HORNEADO"; $words = explode(" ", $descOrden); if (count($words) > 1) { array_pop($words); $baseName = implode(" ", $words); } else { $baseName = $descOrden; } $descSugerida = trim($baseName . " " . $descProcesoActual); $res = DB::table("producto")->where("es_producto_proceso", 1)->where(function($q) use ($descOrden, $descSugerida) { $q->where("descripcion", $descSugerida)->orWhere("descripcion", $descOrden); })->orderByRaw("CASE WHEN descripcion = ? THEN 1 ELSE 2 END", [$descSugerida])->first(); echo json_encode($res);
